let mode='listen',running=false,elapsed=0,activeSeconds=0,sessionCount=0,last=0,stream,ctx,analyser,raf,installPrompt,wakeLock,starting=false,hiddenAt=0,micPending=false,lastDraftAt=0,samplesBuf=null,waveBars=[];
