function persist(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{toast('No se pudo guardar. Exporta tu bitácora para conservarla.')}}
function total(){return data.sessions.reduce((n,s)=>n+s.count,0)}
function allPracticeSessions(){return [...data.sessions,...(data.journeys||[]).flatMap(j=>j.sessions)]}
function localDay(date){return new Date(date).toLocaleDateString('en-CA')}
function toast(t,action){const el=$('#toast');el.textContent='';const span=document.createElement('span');span.textContent=t;el.appendChild(span);clearTimeout(toast.t);if(action){const b=document.createElement('button');b.type='button';b.className='toast-action';b.textContent=action.label;b.onclick=()=>{el.classList.remove('visible');clearTimeout(toast.t);action.onClick()};el.appendChild(b)}el.classList.add('visible');toast.t=setTimeout(()=>el.classList.remove('visible'),action?12000:4500)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function esc(s){const el=document.createElement('span');el.textContent=s;return el.innerHTML.replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function render(){let n=total(),p=Math.min(n/1000000,1);$('#total').textContent=fmt(n);$('#percent').textContent=(p*100).toLocaleString('es-CL',{maximumFractionDigits:2})+' % del viaje';$('#progress-bar').style.width=p*100+'%';$('#today').textContent=fmt(allPracticeSessions().filter(s=>localDay(s.date)===localDay(Date.now())).reduce((a,s)=>a+s.count,0));$('#days').innerHTML=new Set(allPracticeSessions().map(s=>localDay(s.date))).size+' <em>días</em>';$('#next').textContent=n>=1000000?'¡Lo lograste!':fmt(Math.min(1000000,(Math.floor(n/10000)+1)*10000));const dest=stops.find(s=>n<s.end)||stops.at(-1);$('#destination-title').textContent=dest.name;$('#destination-desc').textContent=dest.value;$('.destination small').textContent=n>=1000000?'UN MILLÓN DE POSIBILIDADES CULTIVADAS':dest.zone+' · TU ESTACIÓN ACTUAL';renderMapProgress(n+sessionCount);renderJourneyHistory();refreshMilestone();renderIntentions();renderRegions()}
