 svg.insertAdjacentHTML('beforeend',labels.map(([name,y,x])=>`<path d="M${x+6} ${y}H229" stroke="#829fb5" stroke-width=".7"/><circle cx="${x}" cy="${y}" r="2" fill="#204d70"/><text x="236" y="${y+3}" font-size="10" fill="#345f7d" font-family="sans-serif">${name}</text>`).join(''));
