function regionPhoto(s,i){const photo=REGION_PHOTOS[i];return `<div class="culture-art photo-art photo-zone-${i}"><img src="${photo.src}" alt="${esc(photo.alt)}" width="${photo.width}" height="${photo.height}" loading="lazy" decoding="async"><span>${s.zone} · ${s.icon}</span><div class="photo-location">⌖ ${esc(photo.place)}</div></div>`}
function photoByline(i){const p=REGION_PHOTOS[i]||HERO_PHOTO;return `<div class="photo-byline">Foto: ${esc(p.artist)} · <a href="${p.page}" target="_blank" rel="noopener">Wikimedia Commons</a> · ${p.licenseUrl?`<a href="${p.licenseUrl}" target="_blank" rel="noopener">${esc(p.license)}</a>`:esc(p.license)}</div>`}
function card(s,i,full=false){const n=total(),p=Math.max(0,Math.min(1,(n-s.start)/(s.end-s.start)));return `<button class="culture-card" data-stop="${i}">${regionPhoto(s,i)}<div class="culture-copy"><small>${s.zone}</small><h3>${full?s.name:s.value}</h3><p>${full?s.value:s.name}</p>${full?`<div class="region-progress"><i style="width:${p*100}%"></i></div><span>${fmt(s.start)} — ${fmt(s.end)} daimoku · ${Math.round(p*100)} %</span>`:'<span>Descubrir esta estación ↗</span>'}</div></button>`}
function bindCards(){$$('[data-stop]').forEach(b=>b.onclick=()=>{const i=+b.dataset.stop,s=stops[i];modal(`<span class="eyebrow">${s.zone} · ESTACIÓN ${i+1} DE 7</span><h2>${s.name}</h2><div class="station-photo">${regionPhoto(s,i)}</div>${photoByline(i)}<h3 style="margin-top:20px">${s.value}</h3><p>${s.text}</p><small>Una invitación original a la reflexión. Puedes explorar todas las estaciones desde el primer día.</small><button class="primary" id="station-practice">Llevar esta intención a mi práctica</button>`);$('#station-practice').onclick=()=>{data.intentions.push({id:crypto.randomUUID(),text:s.value,done:false});persist();renderIntentions();$('#modal').close();location.hash='inicio';toast('Intención agregada a tu espacio')}})}

function renderRegions(){$('#regions').innerHTML=stops.map((s,i)=>card(s,i,true)).join('');$('#culture-preview').innerHTML=[0,3,6].map(i=>card(stops[i],i)).join('');bindCards()}
function renderIntentions(){$('#intentions-list').innerHTML=data.intentions.length?data.intentions.map(s=>`<div class="intention ${s.done?'done':''}"><input type="checkbox" aria-label="Marcar intención como cumplida" data-check="${s.id}" ${s.done?'checked':''}><span>${esc(s.text)}</span><button class="delete" data-intention="${s.id}" aria-label="Eliminar intención">×</button></div>`).join(''):'<div class="empty"><span>♡</span>Una intención puede ser el comienzo de algo hermoso.</div>';$$('[data-check]').forEach(c=>c.onchange=()=>{data.intentions.find(s=>s.id===c.dataset.check).done=c.checked;persist();renderIntentions()});$$('[data-intention]').forEach(c=>c.onclick=()=>{data.intentions=data.intentions.filter(s=>s.id!==c.dataset.intention);persist();renderIntentions()})}
$('#intention-form').onsubmit=e=>{e.preventDefault();const text=$('#intention-input').value.trim();if(!text)return;data.intentions.push({id:crypto.randomUUID(),text,done:false});persist();renderIntentions();$('#intention-input').value='';toast('Tu intención ya tiene un lugar')};
function navigate(){const view=['inicio','viaje','bitacora','intenciones'].includes(location.hash.slice(1))?location.hash.slice(1):'inicio';const journey=$('.journey-card');const mapParent=view==='viaje'?$('#route-map-slot'):$('.dashboard');if(journey.parentElement!==mapParent)mapParent.appendChild(journey);$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==view));$$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);a.setAttribute('aria-current',a.dataset.view===view?'page':'false')});$('#page-title').textContent={inicio:'Cada daimoku abre un camino.',viaje:'De norte a sur, paso a paso.',bitacora:'El valor de seguir adelante.',intenciones:'Todo comienza con una intención.'}[view];window.scrollTo(0,0);requestAnimationFrame(()=>window.scrollTo(0,0))}window.onhashchange=navigate;$$('nav a').forEach(a=>a.onclick=e=>{e.preventDefault();history.pushState(null,'',a.getAttribute('href'));navigate()});window.addEventListener('popstate',navigate);$('#explore').onclick=()=>{if(location.hash==='#viaje')$('#regions').scrollIntoView({behavior:'smooth',block:'start'});else location.hash='viaje'};$('#jump-practice').onclick=()=>{location.hash='inicio';setTimeout(()=>$('.practice-card').scrollIntoView({behavior:'smooth',block:'start'}),40)};
$('#wave').innerHTML=Array.from({length:37},(_,i)=>`<i style="height:${5+Math.sin(i*1.7)**2*10}px"></i>`).join('');waveBars=$$('#wave i');
const ui={count:$('#session-count'),timer:$('#timer'),start:$('#start'),finish:$('#finish'),wave:$('#wave'),status:$('#status'),modes:$$('[data-mode]')},shown={};
function sessionLabel(){if(mode==='manual')return '＋ Registrar daimoku';if(running)return mode==='listen'&&micPending?'◉ Reactivar micrófono':'Ⅱ Pausar mi práctica';return sessionCount||elapsed?'▶ Continuar mi práctica':'◉ Comenzar mi daimoku'}
function sessionStatus(){if(!running)return 'A tu ritmo';if(mode==='listen')return micPending?'Micrófono en pausa':'Escuchando sonido';return 'En tu momento'}
function updateSession(){const c=fmt(sessionCount);if(c!==shown.count){ui.count.textContent=c;shown.count=c}const t=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0');if(t!==shown.timer){ui.timer.textContent=t;shown.timer=t}const l=sessionLabel();if(l!==shown.label){ui.start.innerHTML=l;shown.label=l}const f=!elapsed&&!sessionCount;if(f!==shown.finish){ui.finish.classList.toggle('hidden',f);shown.finish=f}if(running!==shown.live){ui.wave.classList.toggle('live',running);shown.live=running}const s=sessionStatus();if(s!==shown.status){ui.status.innerHTML='<i></i> '+s;shown.status=s}const d=running||elapsed>0;if(d!==shown.modes){ui.modes.forEach(b=>b.disabled=d);shown.modes=d}renderMapProgress(total()+sessionCount);refreshMilestone()}
function releaseAudio(){stream?.getTracks().forEach(t=>t.stop());stream=null;if(ctx){const c=ctx;ctx=null;c.close().catch(()=>{})}analyser=null;micPending=false}
async function releaseWakeLock(){try{await wakeLock?.release()}catch{}wakeLock=null}
async function release(){if(raf)cancelAnimationFrame(raf);raf=0;releaseAudio();await releaseWakeLock()}
async function requestWakeLock(){if(!keepAwake||!navigator.wakeLock)return;try{if(wakeLock&&!wakeLock.released)return;const sentinel=await navigator.wakeLock.request('screen');wakeLock=sentinel;sentinel.addEventListener('release',()=>{if(wakeLock===sentinel)wakeLock=null;updateSession()});updateSession()}catch{}}
async function startAudio(){if(mode!=='listen')return;if(!navigator.mediaDevices?.getUserMedia)throw new Error('unsupported');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const c=new(window.AudioContext||window.webkitAudioContext)();ctx=c;try{await Promise.race([c.resume(),new Promise(r=>setTimeout(r,1000))])}catch{}if(c.state!=='running'){ctx=null;try{await c.close()}catch{}stream?.getTracks().forEach(t=>t.stop());stream=null;throw new Error('suspended')}analyser=c.createAnalyser();analyser.fftSize=1024;c.createMediaStreamSource(stream).connect(analyser);c.onstatechange=()=>{if(ctx===c&&c.state!=='running'&&running){micPending=true;updateSession();toast('El audio se interrumpió. Toca «Reactivar micrófono».')}};stream.getAudioTracks()[0].onended=()=>{if(running){micPending=true;updateSession();toast('El micrófono se desconectó. Toca «Reactivar micrófono».')}};micPending=false;samplesBuf=null;updateSession()}
function draft(){if(elapsed||sessionCount){try{localStorage.setItem(KEY+'-draft',JSON.stringify({elapsed,activeSeconds,sessionCount,mode,savedAt:Date.now(),hiddenAt}))}catch{}}}
const clock=s=>{const t=Math.round(Math.max(0,s));return t>=3600?`${Math.floor(t/3600)} h ${String(Math.floor(t%3600/60)).padStart(2,'0')} min`:`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`};
function addGap(gap,raw=gap,quiet=false){const prev={elapsed,activeSeconds,sessionCount},undo=()=>{elapsed=prev.elapsed;activeSeconds=prev.activeSeconds;sessionCount=prev.sessionCount;draft();updateSession();toast('Tiempo devuelto.')};elapsed+=gap;activeSeconds+=gap;sessionCount=Math.floor(activeSeconds*data.rate/60);last=performance.now();lastDraftAt=last;draft();updateSession();if(!quiet&&gap>=8)toast(`Seguimos contando: +${clock(gap)}${raw>gap?' (límite)':''} · ${fmt(Math.floor(gap*data.rate/60))} daimoku.`,{label:'Deshacer',onClick:undo});return{gap,raw,undo}}
function resumeFromHidden(){if(!running||!hiddenAt)return;const raw=Math.max(0,(Date.now()-hiddenAt)/1000),gap=Math.min(MAX_GAP,raw);hiddenAt=0;addGap(gap,raw);if(mode==='listen'&&!analyser)startAudio().catch(()=>{micPending=true;updateSession()});requestWakeLock()}
async function pause(){running=false;draft();await release();updateSession()}
function tick(now){if(!running)return;if(document.hidden){raf=requestAnimationFrame(tick);return}const dt=Math.min((now-last)/1000,.25);last=now;elapsed+=dt;if(mode==='listen'&&analyser&&!micPending){if(!samplesBuf||samplesBuf.length!==analyser.fftSize)samplesBuf=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(samplesBuf);let sum=0;for(let i=0;i<samplesBuf.length;i++)sum+=samplesBuf[i]*samplesBuf[i];const level=Math.sqrt(sum/samplesBuf.length);if(level>data.threshold)activeSeconds+=dt;for(let i=0;i<waveBars.length;i++)waveBars[i].style.height=(4+Math.min(1,level*10)*(8+Math.sin(now/150+i)*18+20))+'px'}else activeSeconds+=dt;sessionCount=Math.floor(activeSeconds*data.rate/60);updateSession();if(now-lastDraftAt>5000){lastDraftAt=now;draft()}raf=requestAnimationFrame(tick)}
async function start(){if(starting)return;if(running){if(mode==='listen'&&micPending)return reviveMic();return pause()}if(mode==='manual')return manual();if(!data.rate)return calibration(true);starting=true;$('#start').disabled=true;try{if(mode==='listen')await startAudio();running=true;hiddenAt=0;last=performance.now();lastDraftAt=last;raf=requestAnimationFrame(tick);await requestWakeLock();updateSession()}catch(e){releaseAudio();toast(e.message==='suspended'?'El audio no pudo activarse. Toca de nuevo para permitirlo.':e.name==='NotAllowedError'?'Micrófono sin permiso. Habilítalo en tu navegador o usa el cronómetro.':'No se pudo activar el micrófono. Puedes usar cronómetro o registro manual.')}finally{starting=false;$('#start').disabled=false}}
async function reviveMic(){if(starting)return;starting=true;$('#start').disabled=true;try{await startAudio();await requestWakeLock();last=performance.now();hiddenAt=0;updateSession();toast('Micrófono reactivado. Seguimos contando.')}catch{micPending=true;updateSession();toast('No se pudo activar el micrófono. Toca de nuevo o revisa el permiso.')}finally{starting=false;$('#start').disabled=false}}
$('#start').onclick=start;$$('[data-mode]').forEach(b=>b.onclick=()=>{if(running||elapsed)return;mode=b.dataset.mode;$$('[data-mode]').forEach(t=>t.classList.toggle('selected',t===b));$('#count-explain').textContent={listen:'Detecta sonido, no reconoce palabras. Estima según tu ritmo.',timer:'El tiempo transcurrido se convierte con tu ritmo personal.',manual:'Registra una práctica anterior o un conteo que ya conoces.'}[mode];$('#privacy').textContent=mode==='listen'?'Audio privado · Sin grabaciones':'Sin acceso al micrófono';$('#start').textContent=mode==='manual'?'＋ Registrar daimoku':'◉ Comenzar mi daimoku'});
function calibration(resume=false){modal('<h2>Tu práctica, a tu ritmo.</h2><p>Cuenta 10 recitaciones completas. Pulsa «Marcar» al comenzar y después de cada una; calcularemos tu ritmo a partir de los 10 intervalos.</p><button class="primary cal-tap" id="tap">Comenzar calibración</button><p id="tap-result" aria-live="polite">Sin un ritmo universal: aquí usamos el tuyo.</p><label for="rate">O escribe tu ritmo (daimoku por minuto)</label><input id="rate" type="number" min="1" max="300" step="0.1" value="'+(data.rate||'')+'" placeholder="Tu ritmo personal"><label for="sensitivity">Umbral de sonido</label><select id="sensitivity"><option value="0.012">Voz suave · lugar silencioso</option><option value="0.025">Voz normal</option><option value="0.06">Menor sensibilidad · ruido de fondo</option></select><label class="wake-option"><input type="checkbox" id="wake-keep"'+(keepAwake?' checked':'')+'> Mantener la pantalla encendida durante la práctica</label><small>El modo con voz estima tiempo con sonido: también puede detectar música, conversaciones o ruido. No reconoce Nam-myoho-renge-kyo. Revisa el resultado al guardar.</small><button class="primary" id="save-rate">Guardar mi ritmo</button>');$('#sensitivity').value=String(data.threshold);let taps=[];$('#tap').onclick=()=>{taps.push(performance.now());$('#tap').textContent=taps.length===1?'Marcar recitación 1 de 10':`Marcar recitación ${Math.min(taps.length,10)} de 10`;$('#tap-result').textContent=`${Math.max(0,taps.length-1)} de 10 recitaciones completadas`;if(taps.length===11){const rate=600000/(taps[10]-taps[0]);if(rate>=1&&rate<=300){$('#rate').value=rate.toFixed(1);$('#tap-result').textContent='Tu ritmo: '+rate.toFixed(1)+' daimoku/min';$('#tap').disabled=true}else{taps=[];$('#tap-result').textContent='Ese ritmo está fuera de rango. Vuelve a marcar cada recitación completa.'}}};$('#save-rate').onclick=()=>{const rate=Number($('#rate').value);if(!Number.isFinite(rate)||rate<1||rate>300)return toast('Indica un ritmo entre 1 y 300 daimoku/min.');data.rate=rate;data.threshold=Number($('#sensitivity').value);persist();keepAwake=$('#wake-keep').checked;try{localStorage.setItem('daimoku-chile-wakelock',keepAwake?'1':'0')}catch{}if(!keepAwake)releaseWakeLock();$('#modal').close();toast('Ritmo guardado: '+rate+' daimoku/min');if(resume)start()}}
$('#calibrate').onclick=()=>{if(running||elapsed)return toast('Guarda o descarta la sesión antes de ajustar el ritmo.');calibration()};$('#settings').onclick=$('#calibrate').onclick;
function saveSession(count,seconds,selectedMode){data.sessions.push({id:crypto.randomUUID(),date:new Date().toISOString(),count,seconds,mode:selectedMode,rate:data.rate});persist();elapsed=0;activeSeconds=0;sessionCount=0;localStorage.removeItem(KEY+'-draft');updateSession();render();$('#modal').close();toast(total()>=1000000?'¡Un millón! Chile se ha iluminado con tu práctica.':'Sesión guardada. Tu camino sigue creciendo.');}
$('#finish').onclick=async()=>{await pause();modal(`<h2>Un paso más en tu camino.</h2><p>Has dedicado ${Math.floor(elapsed/60)} min ${Math.floor(elapsed%60)} s. ${mode==='listen'?'El conteo estima el tiempo con sonido; no identifica las palabras recitadas.':'El conteo se estima con tu ritmo personal.'} Puedes corregirlo antes de guardar.</p><label for="review-count">Daimoku de esta sesión</label><input id="review-count" type="number" min="1" max="1000000" step="1" value="${sessionCount}"><button class="primary" id="save-session">Guardar en mi viaje</button><button class="text-button" id="discard">Descartar esta sesión</button>`);$('#save-session').onclick=()=>{const n=Number($('#review-count').value);if(!Number.isInteger(n)||n<1||n>1000000)return toast('Ingresa entre 1 y 1.000.000 daimoku.');saveSession(n,elapsed,mode)};$('#discard').onclick=()=>{elapsed=activeSeconds=sessionCount=0;localStorage.removeItem(KEY+'-draft');updateSession();$('#modal').close();toast('Sesión descartada')}};
function manual(){modal('<h2>Cada práctica cuenta.</h2><p>Añade un conteo que ya conozcas. Se sumará a tu mapa y a la bitácora de hoy.</p><label for="manual-count">Cantidad de daimoku</label><input id="manual-count" type="number" min="1" max="1000000" step="1" placeholder="Ej. 1.000"><label for="manual-minutes">Duración en minutos (opcional)</label><input id="manual-minutes" type="number" min="0" max="1440" value="0"><button class="primary" id="save-manual">Agregar a mi viaje</button>');$('#save-manual').onclick=()=>{const n=Number($('#manual-count').value),m=Number($('#manual-minutes').value);if(!Number.isInteger(n)||n<1||n>1000000||!Number.isFinite(m)||m<0||m>1440)return toast('Revisa la cantidad y la duración.');saveSession(n,m*60,'manual')}}
function about(){modal('<h2>Un conteo con sentido.</h2><p>Una unidad representa una recitación completa de Nam-myoho-renge-kyo. No hemos verificado una tasa oficial de Soka Gakkai por minuto. El ritmo se calibra individualmente.</p><p><b>Con mi voz:</b> el micrófono detecta actividad sonora y la convierte en una estimación según tu ritmo. No distingue recitación de otros sonidos. <b>Cronómetro:</b> convierte todo el tiempo transcurrido. <b>Manual:</b> registra un número conocido.</p><p>Si la pantalla se apaga o sales de la app, el tiempo ausente se suma con tu ritmo al volver; el aviso permite deshacerlo. Con la pantalla encendida, el modo con voz sigue midiendo el sonido sin interrupciones.</p><p>El mapa tiene 1.000 cuadros: cada uno equivale a 1.000 daimoku. Se llena de norte a sur; el total puede continuar después del millón.</p><p>Esta es una aplicación independiente, sin afiliación ni aval de SGI. La meta de un millón es personal y no mide el valor de tu práctica.</p><small>Fuentes: <a target="_blank" rel="noopener" href="https://www.sokaglobal.org/resources/videos/how-to-chant.html">Cómo recitar · Soka Gakkai</a> · <a target="_blank" rel="noopener" href="https://www.sokaglobal.org/resources/sg-charter.html">Carta de Soka Gakkai</a> · <a target="_blank" rel="noopener" href="https://play.google.com/store/apps/details?id=com.daimokupro.DAIMOKUPRO">DAIMOKU PRO, referencia funcional</a></small><h3 style="margin-top:20px">Tu privacidad</h3><p>No grabamos ni enviamos audio. Sesiones e intenciones se guardan en este navegador. No hay sincronización entre dispositivos. Exporta tus datos antes de borrar el almacenamiento del navegador.</p>')}
$('#about').onclick=about;$('#sources').onclick=about;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal('<h2>Tu camino, siempre a mano.</h2><p>En Android o Chrome, abre el menú del navegador y elige «Instalar aplicación» o «Añadir a pantalla de inicio».</p><p>En iPhone o iPad, abre esta página en Safari, pulsa Compartir y elige «Añadir a pantalla de inicio».</p><small>La instalación depende de tu navegador. Después de la primera visita, la interfaz y tus registros funcionan sin conexión. El micrófono requiere permiso y una página segura (HTTPS).</small>')};
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(running&&!hiddenAt){hiddenAt=Date.now();draft();releaseAudio();releaseWakeLock();updateSession()}}else resumeFromHidden()});
window.addEventListener('pagehide',()=>{if(running&&!hiddenAt)hiddenAt=Date.now();draft();if(running)releaseAudio();releaseWakeLock()});
makeMap();initMapControls();render();navigate();try{const saved=JSON.parse(localStorage.getItem(KEY+'-draft'));if(saved&&saved.elapsed>0){elapsed=saved.elapsed;activeSeconds=saved.activeSeconds;sessionCount=saved.sessionCount;mode=saved.mode;$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));let added=null;if(saved.hiddenAt){const raw=Math.max(0,(Date.now()-saved.hiddenAt)/1000),gap=Math.min(MAX_GAP,raw);hiddenAt=0;added=addGap(gap,raw,true)}updateSession();if(added&&added.gap>=8)toast(`Recuperamos tu sesión pendiente. Sumamos ${clock(added.gap)}${added.raw>added.gap?' (límite)':''} · ${fmt(Math.floor(added.gap*data.rate/60))} daimoku.`,{label:'Deshacer',onClick:added.undo});else toast('Recuperamos tu sesión pendiente. Puedes continuar o guardarla.')}}catch{}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});


$('#install-mobile').onclick=$('#install').onclick;


function applyTheme(theme,remember=true){
 if(!['light','dim','dark'].includes(theme))theme='dim';
 document.documentElement.dataset.theme=theme;
 $$('[data-theme-choice]').forEach(b=>{b.classList.toggle('selected',b.dataset.themeChoice===theme);b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme))});
 $('meta[name="theme-color"]').setAttribute('content',{light:'#f6f7f9',dim:'#192636',dark:'#0b1119'}[theme]);
 if(remember){try{localStorage.setItem('daimoku-chile-theme',theme)}catch{}}
}
$$('[data-theme-choice]').forEach(b=>b.onclick=()=>applyTheme(b.dataset.themeChoice));
applyTheme(document.documentElement.dataset.theme||'dim',false);

$('#photo-credits').onclick=()=>modal(`<h2>Chile, a través de sus miradas.</h2><p>Fotografías reales de Chile, seleccionadas de Wikimedia Commons. Se optimizaron en WebP y se adaptó el encuadre a cada tarjeta. Cada imagen conserva su licencia indicada.</p><div class="photo-credits-list">${[...REGION_PHOTOS,HERO_PHOTO].map((p,i)=>`<article><h3>${esc(p.place)}</h3>${photoByline(i)}</article>`).join('')}</div>`);

initJourneyExports();
